function agg(rs){return {n:rs.length, e5:rs.filter(r=>r.status>=500).length};}
print('TOTALS stable', JSON.stringify(agg(stable)), 'canary', JSON.stringify(agg(canary)));
var paths = [...new Set(rows.map(r=>r.path))];
for (const p of paths){
  const s = stable.filter(r=>r.path===p), c = canary.filter(r=>r.path===p);
  print('PATH', p, 'stable n='+s.length+' 5xx='+agg(s).e5, '| canary n='+c.length+' 5xx='+agg(c).e5,
    '| p95 stable='+pct(s.map(r=>r.ms),95)+' canary='+pct(c.map(r=>r.ms),95));
}
print('--- canary 5xx rows ---');
canary.filter(r=>r.status>=500).forEach(r=>print('t='+r.t.toFixed(1), r.path, r.status, r.ms+'ms'));
print('--- 30s windows: canary 5xx / stable 5xx / p95 ---');
for (let w=0; w<120; w+=30){
  const cw = canary.filter(r=>r.t>=w && r.t<w+30), sw = stable.filter(r=>r.t>=w && r.t<w+30);
  print(w+'-'+(w+30)+'s canary5xx='+agg(cw).e5+' stable5xx='+agg(sw).e5+' canaryP95='+pct(cw.map(r=>r.ms),95)+' stableP95='+pct(sw.map(r=>r.ms),95));
}
print('--- distinct canary 5xx statuses ---');
print(JSON.stringify([...new Set(canary.filter(r=>r.status>=500).map(r=>r.status))]));

const c5=canary.filter(r=>r.status>=500), s5=stable.filter(r=>r.status>=500);
print("CANARY_5XX="+c5.length+" STABLE_5XX="+s5.length);
print("CANARY_5XX_PATHS="+JSON.stringify([...new Set(c5.map(r=>r.path))]));
const cc=canary.filter(r=>r.path==="/checkout"), sc=stable.filter(r=>r.path==="/checkout");
const cce=cc.filter(r=>r.status>=500).length, sce=sc.filter(r=>r.status>=500).length;
print("CHECKOUT canary 5xx="+cce+" of "+cc.length+" ("+(100*cce/cc.length).toFixed(2)+"%) stable 5xx="+sce+" of "+sc.length);
const w=[0,30,60,90].map(s=>canary.filter(r=>r.t>=s&&r.t<s+30&&r.status>=500).length);
print("W0-30="+w[0]+" W30-60="+w[1]+" W60-90="+w[2]+" W90-120="+w[3]+" SUM="+w.reduce((a,b)=>a+b,0));
const cp=pct(canary.map(r=>r.ms),95), sp=pct(stable.map(r=>r.ms),95);
print("P95 canary="+cp+" stable="+sp+" LATENCY_CANARY_NOT_WORSE="+(cp<=sp+10));
const cp99=pct(canary.map(r=>r.ms),99), sp99=pct(stable.map(r=>r.ms),99);
print("P99 canary="+cp99+" stable="+sp99);

